import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  'ml-fundamentals': [
    L('What is machine learning?',
      info('Learning from examples', 'In ordinary programming you write the rules. In **machine learning** you give examples and the computer finds the rules.\n\n- **Features (X):** what we know, such as size and location of a flat.\n- **Target (y):** what we want to predict, such as its price.\n- **Model:** the learned mapping from X to y.'),
      match('Match the type of learning', [['Supervised', 'Examples come with the right answer'], ['Unsupervised', 'No answers: find structure such as clusters'], ['Reinforcement', 'Learn from rewards by acting'], ['Self-supervised', 'The data provides its own labels']]),
      mc('Predicting the price of a flat is…', ['Regression', 'Classification', 'Clustering', 'Reinforcement learning'], 'The target is a number.'),
      mc('Deciding whether an email is spam is…', ['Classification', 'Regression', 'Clustering', 'Dimensionality reduction'], 'The target is a category.'),
      mc('You have customer data and no labels, and want to find groups of similar customers. Which approach?', ['Clustering', 'Classification', 'Regression', 'Supervised ranking'], 'Unsupervised: no target is given.'),
      fill('The values the model learns during training are called its ___.', ['parameters', 'features', 'labels', 'metrics'], 'Settings you choose before training, such as the learning rate, are hyperparameters.'),
      tf('A model that scores 100% on the data it was trained on is guaranteed to work on new data.', false, 'It may simply have memorised the examples.'),
      order('Order a basic ML project', ['Define the problem and the metric', 'Collect and clean data', 'Split into training and test sets', 'Train a model', 'Evaluate on data it has not seen'], 'The test set stays hidden until the end.')),

    L('Generalisation: train, validate, test',
      info('The only score that matters', 'We care how the model does on **new** data. So we hide part of the data:\n\n- **Training set:** the model learns from it.\n- **Validation set:** you tune choices on it.\n- **Test set:** used once, at the end, for an honest estimate.'),
      mc('You tune hyperparameters on the test set until the score is great. What is wrong?', ['The test score is now optimistic: you fitted to it', 'Nothing', 'Training becomes slower', 'The model shrinks'], 'Tune on validation data; touch the test set once.'),
      info('Underfitting and overfitting', '**Underfitting:** the model is too simple. Poor on training and validation.\n\n**Overfitting:** the model memorises noise. Excellent on training, poor on validation.\n\nThe gap between training and validation scores tells you which.'),
      mc('Training accuracy 99%, validation accuracy 70%. Diagnosis?', ['Overfitting', 'Underfitting', 'Perfect fit', 'Data leakage for sure'], 'A large gap means high variance.'),
      mc('Training accuracy 62%, validation accuracy 60%. Diagnosis?', ['Underfitting', 'Overfitting', 'Leakage', 'A great model'], 'Both low: the model cannot capture the pattern.'),
      match('Match the problem to a fix', [['Overfitting', 'More data, regularisation, simpler model'], ['Underfitting', 'Richer model or better features'], ['Unstable validation score', 'Cross-validation'], ['Imbalanced classes', 'Stratified splits']]),
      type('In 5-fold cross-validation, what percentage of the data is used for validation in each round?', ['20', '20%'], 'One fold of five.'),
      mc('Sales data from 2021 to 2025. How should you validate?', ['Train on earlier years, validate on later ones', 'Random k-fold', 'Validate on the training data', 'Shuffle first'], 'Random splits let the model see the future.')),

    L('Leakage and regularisation',
      info('Data leakage', '**Leakage** means the model is trained with information it will not have when it is used. Scores look fantastic, then production fails.\n\nTypical causes: fitting a scaler on all data before splitting, a feature recorded after the outcome, the same customer in both train and test.'),
      mc('Which is leakage?', ['Computing the mean for imputation on the full dataset before splitting', 'Using dropout', 'Shuffling the training set', 'Using a validation set'], 'The test rows influenced a training statistic.'),
      order('The safe order of operations', ['Split the data', 'Fit the scaler on the training set only', 'Transform training and test sets with it', 'Train the model', 'Evaluate on the test set'], 'Split first, fit preprocessing on training data only.'),
      mc('To predict loan default at application time you use the feature "number of missed payments on this loan". Problem?', ['It is only known after the outcome: target leakage', 'It is categorical', 'It has too many values', 'None'], 'Ask of every feature: would I know this at prediction time?'),
      info('Regularisation', 'Penalise complexity so the model does not chase noise.\n\n- **L2 (ridge):** shrinks all weights smoothly.\n- **L1 (lasso):** pushes some weights to exactly zero, selecting features.\n\nIn deep learning: dropout, weight decay, early stopping, augmentation.'),
      mc('Which regulariser can remove features entirely?', ['L1', 'L2', 'Dropout', 'Batch norm'], 'It drives weights to exactly zero.'),
      mc('Increasing regularisation strength usually…', ['Lowers variance and raises bias', 'Raises variance and lowers bias', 'Lowers both', 'Changes nothing'], 'The model gets simpler.'),
      tf('A scikit-learn Pipeline helps prevent leakage in cross-validation.', true, 'Preprocessing is re-fitted inside each training fold.')),

    L('Bias, variance and interview level',
      info('The trade-off', 'Error = **bias** + **variance** + noise.\n\n**Bias:** wrong assumptions, model too simple. **Variance:** sensitivity to the particular training sample, model too flexible.\n\nMore complexity lowers bias and raises variance. We look for the lowest validation error.'),
      match('Match the term', [['High bias', 'Underfits: misses the pattern'], ['High variance', 'Overfits: changes a lot with the data'], ['Irreducible error', 'Noise no model can remove'], ['Learning curve', 'Score against training-set size']]),
      mc('A learning curve shows training and validation scores both low and close together. More data will…', ['Not help much: the model is too simple', 'Fix it', 'Cause overfitting', 'Reduce bias'], 'High bias needs a better model or features.'),
      mc('Bagging (as in random forests) mainly reduces…', ['Variance', 'Bias', 'Noise', 'Training time'], 'Averaging many unstable models smooths their errors.'),
      mc('First model you should try on a new tabular problem?', ['A simple baseline such as logistic regression or gradient-boosted trees', 'The largest neural network available', 'A custom transformer', 'No model'], 'It is fast, hard to get badly wrong and sets the bar.'),
      order('Order a strong answer to "How do you handle overfitting?"', ['Confirm it from the train/validation gap', 'Check for leakage and a representative split', 'Add data or augmentation, and regularise', 'Simplify the model or stop early', 'Confirm the fix with cross-validation'], 'Diagnose before you treat.'),
      mc('Interviewer: "When would you NOT use machine learning?"', ['When simple rules solve it, or there is no data or no way to measure success', 'Never', 'When the dataset is large', 'When a GPU is available'], 'Judgement about when not to use ML is a senior signal.'),
      tf('A more complex model is always better if you have enough compute.', false, 'It may overfit, be harder to maintain and cost more for no gain.')),

    L('Deeper ideas: models, search and splits',
      info('Parametric or not', 'A **parametric** model has a fixed number of parameters whatever the data size: a linear model with 10 features always has 11 numbers to learn.\n\nA **non-parametric** model grows with the data: k-nearest neighbours keeps every training row, and a tree adds splits as it sees more examples.\n\nEvery model also carries an **inductive bias**: built-in assumptions about what a good answer looks like.'),
      match('Match the model to its nature', [['Linear regression', 'Fixed number of weights'], ['k-nearest neighbours', 'Stores the training data itself'], ['Decision tree', 'Gets more splits with more data'], ['Convolutional network', 'Assumes nearby pixels are related']]),
      type('Grid search tries 4 learning rates and 3 tree depths, each with 5-fold cross-validation. How many models are fitted?', ['60'], '4 × 3 × 5 = 60.'),
      mc('With the same budget of 60 fits, why is random search often better than grid search?', ['It tries more distinct values of the hyperparameters that matter', 'It always finds the global optimum', 'It needs no validation set', 'It removes the need for a baseline'], 'A grid repeats the same few values of each hyperparameter; random draws are all different.'),
      info('When rows are not independent', 'A plain random split assumes each row is independent. Often it is not:\n\n- **Stratified k-fold** keeps the class proportions the same in every fold.\n- **Group k-fold** keeps all rows of one patient, user or machine in the same fold.\n- **Time-series split** always validates on data that comes after the training data.\n- **Nested cross-validation** adds an outer loop so the score is not inflated by the tuning done in the inner loop.'),
      tf('Stratified k-fold keeps the proportion of each class roughly equal across folds.', true, 'Important when a class is rare.'),
      mc('You have 10,000 scans from 200 patients (about 50 each). A random split puts scans of one patient in both train and test. What is the effect?', ['The test score is too optimistic because the model recognises patients', 'The test score is too pessimistic', 'No effect, rows are independent', 'The model cannot train'], 'Use group k-fold with the patient as the group.'),
      mc('You tune hyperparameters with 5-fold cross-validation and report the best fold-average. What does nested cross-validation fix?', ['The reported score is biased upwards because you picked the best of many', 'The model becomes more complex', 'Training becomes faster', 'It removes the need for a test set entirely'], 'An outer loop scores the whole tuning procedure on data it never touched.')),

    L('Common mistakes and debugging',
      info('If the score looks too good, suspect a bug', 'A new model that scores 99.9% is far more likely to have a **bug** than to be a breakthrough. Real problems have noise.\n\nBefore celebrating: look for duplicates between train and test, features that are really the label in disguise, and preprocessing done before the split.'),
      tf('A surprisingly high test score should first be treated as a possible bug.', true, 'Check for leakage before reporting it.'),
      mc('What is wrong with this evaluation?', ['It reports accuracy on the training data, which says nothing about new data', 'It uses accuracy', 'It calls fit before score', 'It has no random seed'], 'Score on a held-out set.', 'model.fit(X_train, y_train)\nprint("accuracy:", model.score(X_train, y_train))'),
      mc('The same customer appears in 3 rows, and a random split puts one row in train and two in test. What follows?', ['The model gets partly rewarded for remembering customers', 'The test score is too low', 'The model underfits', 'Nothing, it is a normal split'], 'Deduplicate, or split by customer.'),
      mc('Which bug is hidden in this code?', ['The class numbers can differ between the two sets whenever a class is missing from one', 'LabelEncoder is too slow', 'The test set is too small', 'It uses strings'], 'Fit the encoder once on training labels, then only transform.', 'enc = LabelEncoder()\ny_train = enc.fit_transform(y_train)\ny_test = enc.fit_transform(y_test)'),
      mc('Daily sales data is split like this. What is wrong?', ['Shuffling lets the model train on days that come after the test days', 'It uses too few rows', 'It should be test_size=0.5', 'Nothing'], 'For time data cut by date instead.', 'df = df.sample(frac=1, random_state=0)\ntrain, test = df[:800], df[800:]'),
      fill('To make a split give the same rows every run, set the random ___.', ['seed', 'depth', 'threshold', 'margin'], 'Reproducibility matters when you compare experiments.'),
      info('Debugging checklist', '1. **Overfit a tiny sample** (say 20 rows). If the model cannot reach near-zero loss, the pipeline is broken.\n2. Compare against a **dummy baseline**.\n3. **Look at the data**: histograms, missing values, the worst predictions.\n4. Change **one thing at a time** and log each experiment.'),
      mc('Training loss is NaN after a few steps. Which cause is most likely?', ['A learning rate that is too high, or log(0) in the loss', 'Too few trees', 'A stratified split', 'Too small a test set'], 'Lower the rate, scale the inputs and clip probabilities away from 0 and 1.'),
      order('Debugging a model that scores 0.90 offline but 0.55 online', ['Check that online features are computed with the same code as offline', 'Compare feature distributions between training and live data', 'Check that the offline split matched the real prediction moment', 'Fix the pipeline mismatch or retrain on recent data', 'Re-measure online with a held-out group'], 'Look for training-serving mismatch before blaming the algorithm.')),

    L('Case study: predicting customer churn',
      info('The situation', 'A subscription service has **100,000 customers**. About **5%** cancel each month. The retention team can phone **2,000** customers a month. An offer costs **20** per customer reached, and a customer who stays instead of leaving is worth **300**. Your job: decide whom to phone.'),
      mc('Step 1: how do you define the prediction?', ['Will this customer cancel in the next 30 days, using only data known at the start of the month', 'Will the customer ever cancel, using all data to date', 'How many customers will cancel, using next month’s tickets', 'Which customers are unhappy, using survey answers from after they left'], 'Fix the prediction moment, and use nothing from after it.'),
      mc('Step 2: how do you split the data?', ['Train on older months, validate on a later month, test on the latest', 'Random 80/20 over all customer-months', 'Test on the oldest months', 'Use the full data for both'], 'The model will always be used on the future.'),
      type('Step 3: if you phone 2,000 customers at random, how many of them are expected to be future churners?', ['100'], '5% of 2,000.'),
      info('Evaluate for the way it is used', 'Only the **top 2,000** scores will be phoned, so **precision at 2,000** and **lift** matter more than overall accuracy or AUC.\n\n**Lift** = precision in the selected group ÷ the base rate.'),
      type('Step 4: your model’s top 2,000 contain 500 real churners. What is the lift over random?', ['5', '5x', '5.0'], 'Precision 500/2,000 = 25%, and 25% ÷ 5% = 5.'),
      mc('Step 5: which metric should you report to the team?', ['Precision at the top 2,000, with lift', 'Accuracy over all customers', 'R²', 'Training loss'], 'It mirrors the phone budget.'),
      type('Step 6: the offer saves 30% of the churners it reaches. What is the net benefit of calling the model’s 2,000 (500 churners)?', ['5000', '5,000'], '500 × 0.3 × 300 = 45,000, minus 2,000 × 20 = 40,000.'),
      mc('Step 7: how do you prove it works after launch?', ['Hold out a random control group among the selected customers and compare churn', 'Compare this month with last month', 'Ask the team if they like it', 'Re-check the offline AUC'], 'Only a randomised comparison separates the model’s effect from seasonality.'),
      order('Order the project', ['Define the prediction moment and the label', 'Build features from data known at that moment', 'Split by time and train a baseline', 'Evaluate precision at 2,000 and net benefit', 'Run a randomised pilot with a control group'], 'Define, build, validate, then prove it live.')),

    L('Interview drill: ML fundamentals',
      info('How interviewers probe', 'They ask a plain question, then **follow up** to see whether you really understand: "How do you know?", "What if the data is time-ordered?", "What would you check next?"\n\nA strong answer names the **risk**, gives a **concrete check** and says what you would do if it fails.'),
      mc('"How do you know your model will generalise?" Best answer?', ['Score data it never influenced, split to match real use, repeat with cross-validation, then monitor live', 'Training accuracy is high', 'The loss is low', 'The model is large'], 'Held-out evidence, then monitoring.'),
      mc('Follow-up: "Cross-validation gives 0.91 but the test set gives 0.84. What next?"', ['Look for leakage in the folds and a different distribution in the test set', 'Report 0.91', 'Add more trees', 'Remove the test set'], 'A gap means the two estimates measure different things.'),
      match('Match the question to what it tests', [['Why not just use accuracy?', 'Class imbalance and error costs'], ['How would you split the data?', 'Leakage and time order'], ['It got worse after launch', 'Drift and monitoring'], ['Simple or complex model?', 'Trade-off judgement']]),
      mc('Follow-up: "Three months after launch the model gets worse. First hypothesis?"', ['The inputs or the relationship changed: drift', 'The test set was too small', 'Gradient descent stopped working', 'The code was recompiled'], 'Compare current feature distributions with training and retrain if needed.'),
      fill('A model that works offline but fails live often suffers training-serving ___.', ['skew', 'depth', 'momentum', 'entropy'], 'Features were computed differently in the two places.'),
      info('A shape for your answers', '1. **Clarify** the goal and what each error costs.\n2. Start with a **baseline**.\n3. Decide with a **number**, not a feeling.\n4. Name the **risks** (leakage, drift, imbalance).\n5. Say how you would **verify** it in production.'),
      order('Order the parts of a strong answer to "Design a model to predict X"', ['Clarify the goal, the prediction moment and the cost of errors', 'Propose a simple baseline', 'Describe features and the split that avoids leakage', 'Choose metrics that match the costs', 'Explain monitoring and a plan for drift'], 'Structure shows you have shipped models before.'),
      tf('Answering "it depends" is strong when you then say what it depends on.', true, 'Naming the factors is the signal; the phrase alone is not.'))
  ],

  metrics: [
    L('Right and wrong: the confusion matrix',
      info('Four outcomes', 'For a yes/no prediction there are four cases:\n\n- **True positive (TP):** said yes, was yes.\n- **False positive (FP):** said yes, was no. A false alarm.\n- **False negative (FN):** said no, was yes. A miss.\n- **True negative (TN):** said no, was no.'),
      match('Match the outcome', [['True positive', 'Flagged fraud, really fraud'], ['False positive', 'Flagged fraud, actually fine'], ['False negative', 'Not flagged, actually fraud'], ['True negative', 'Not flagged, actually fine']]),
      type('TP = 40, TN = 50, FP = 5, FN = 5. What is the accuracy in percent?', ['90', '90%'], '(40 + 50) / 100.'),
      info('The accuracy trap', 'If 1% of transactions are fraud, a model that always says "not fraud" is 99% accurate and completely useless.\n\nWith **imbalanced** classes, accuracy hides failure. We need metrics that focus on the rare class.'),
      type('1,000 emails, 10 are spam. A model predicts "not spam" for all. What is its accuracy in percent?', ['99', '99%'], '990 correct out of 1,000.'),
      mc('How many spam emails did that model catch?', ['None', 'All', 'Half', '99%'], 'Which is why accuracy is the wrong metric here.'),
      tf('Accuracy is a reliable metric when classes are balanced.', true, 'The trouble starts with imbalance or unequal error costs.'),
      mc('A false negative in cancer screening means…', ['A patient with cancer was told they are fine', 'A healthy patient was sent for more tests', 'The test was not run', 'The result was correct'], 'Usually the costlier error in this setting.')),

    L('Precision, recall and F1',
      info('Two questions', '**Precision:** of everything I flagged, how much was right? `TP / (TP + FP)`\n\n**Recall:** of everything that was really positive, how much did I find? `TP / (TP + FN)`\n\n**F1:** their harmonic mean, one number that needs both to be good.'),
      type('TP = 8, FP = 2. What is the precision?', ['0.8', '.8', '80%'], '8 / (8 + 2).'),
      type('TP = 8, FN = 8. What is the recall?', ['0.5', '.5', '50%'], '8 / (8 + 8).'),
      fillc('recall = tp / (tp + ___)', ['fn', 'fp', 'tn', 'tp'], 'All actual positives: those found plus those missed.'),
      mc('A spam filter must never hide a real email. Prioritise…', ['Precision', 'Recall', 'Accuracy', 'Specificity'], 'False positives are the costly error.'),
      mc('A screening test must not miss disease. Prioritise…', ['Recall', 'Precision', 'Accuracy', 'F1 only'], 'False negatives are the costly error.'),
      mc('Precision 1.0 and recall 0.02. What is the model doing?', ['Flagging almost nothing, but always correctly', 'Flagging everything', 'Working perfectly', 'Guessing randomly'], 'Easy to be precise when you rarely commit.'),
      type('Precision = 0.5 and recall = 0.5. What is F1?', ['0.5', '.5'], '2·p·r / (p + r).')),

    L('Thresholds, ROC and PR curves',
      info('The dial', 'Most models output a **score** between 0 and 1. A **threshold** turns it into yes or no.\n\nLower the threshold: you flag more, recall rises, precision falls. Raise it: the opposite.\n\nThe model does not choose the threshold. The **cost of errors** does.'),
      mc('You lower the threshold from 0.5 to 0.2. What happens?', ['Recall goes up, precision usually goes down', 'Both go up', 'Both go down', 'Nothing changes'], 'More items are flagged, including more false alarms.'),
      info('ROC and AUC', 'The **ROC curve** plots true-positive rate against false-positive rate at every threshold. **AUC** is the area under it.\n\nAUC = the probability that a random positive gets a higher score than a random negative. 0.5 is random, 1.0 is perfect.'),
      mc('AUC = 0.5 means the model…', ['Ranks no better than chance', 'Is perfect', 'Is always wrong', 'Has 50% accuracy at every threshold'], 'Coin-flip ranking.'),
      mc('An AUC of 0.1 suggests…', ['The scores are inverted: flip them and you have 0.9', 'A perfect model', 'Random guessing', 'Too little data'], 'Consistently wrong is informative.'),
      mc('For a 0.1% fraud rate, which curve is more informative?', ['Precision-recall', 'ROC', 'The loss curve', 'A histogram'], 'ROC can look excellent while precision is terrible.'),
      tf('AUC depends on the classification threshold you choose.', false, 'It summarises ranking quality across all thresholds.'),
      mc('"Calibrated" probabilities mean…', ['Of all cases given 0.8, about 80% are positive', 'Scores are between 0 and 1', 'The AUC is high', 'The threshold is 0.5'], 'Needed when the probability itself is used, for example in expected cost.')),

    L('Regression, ranking and interview level',
      info('Regression metrics', '**MAE:** mean absolute error, in the target’s units, robust to outliers.\n\n**RMSE:** square root of the mean squared error; punishes large errors.\n\n**R²:** share of variance explained.'),
      type('Errors of -2, 2, -2, 2. What is the MAE?', ['2', '2.0'], 'Mean of the absolute values.'),
      mc('One prediction is off by 100 while the rest are off by 1. Which metric reacts most?', ['RMSE', 'MAE', 'Median absolute error', 'They react equally'], 'Squaring magnifies large errors.'),
      match('Match the task to a metric', [['Search ranking', 'NDCG'], ['Summarisation', 'ROUGE'], ['Object detection', 'mAP'], ['Forecasting across products', 'MASE']]),
      mc('Offline AUC improved, yet the A/B test shows no change in revenue. Most likely?', ['The offline metric is a weak proxy for the business goal', 'A/B tests do not work', 'AUC is always wrong', 'The model is too fast'], 'Validate that your offline metric tracks the online outcome.'),
      order('Order a strong answer to "Which metric would you use?"', ['Ask what each kind of error costs the business', 'Check the class balance', 'Choose the metric and the threshold from those costs', 'Confirm with an online test'], 'Metrics follow costs, not habit.'),
      mc('Fraud detection with reviewers who can check 100 cases a day. Most useful metric?', ['Precision in the top 100 scored cases', 'Accuracy', 'R²', 'Training loss'], 'Match the metric to how predictions are used.'),
      mc('Macro-averaged F1 differs from micro-averaged F1 because it…', ['Gives each class equal weight, whatever its size', 'Ignores small classes', 'Is always higher', 'Uses a different formula for precision'], 'Use macro when rare classes matter.'),
      tf('You should report a confidence interval or variation across folds, not only one number.', true, 'A difference of 0.2% may be noise.')),

    L('Deeper metrics: specificity, F-beta, probabilities',
      info('More from the confusion matrix', '- **Specificity:** `TN / (TN + FP)`. Of the real negatives, how many did I clear?\n- **False-positive rate:** `1 - specificity`. This is the x-axis of the ROC curve.\n- **Balanced accuracy:** the mean of recall and specificity, so each class counts equally.\n- **F-beta:** like F1 but recall counts beta times as much as precision. F2 favours recall, F0.5 favours precision.'),
      type('TN = 90 and FP = 10. What is the specificity?', ['0.9', '.9', '90%'], '90 / (90 + 10).'),
      mc('Which quantity is on the y-axis of the ROC curve?', ['True-positive rate, which is recall', 'Precision', 'Accuracy', 'Specificity'], 'The x-axis is the false-positive rate.'),
      type('1% of transactions are fraud and a model always says "not fraud". What is its balanced accuracy?', ['0.5', '.5', '50%'], 'Recall 0 and specificity 1, so the mean is 0.5.'),
      mc('You must catch as many positives as possible and can tolerate some false alarms. Which score fits best?', ['F2', 'F0.5', 'Accuracy', 'Specificity'], 'F2 weights recall more heavily than precision.'),
      info('Scoring the probabilities themselves', '**Log-loss** punishes confident wrong probabilities. The **Brier score** is the mean squared error of the probabilities: `mean((p - y)²)`, where y is 0 or 1. Lower is better.\n\nThe baseline of a random classifier on a precision-recall curve is the **positive rate**, not 0.5.'),
      type('A classifier guesses at random on data with 2% positives. What precision does it get, in percent?', ['2', '2%'], 'Random flags are positive as often as the data is.'),
      type('Predictions p = 0.8 (true y = 1) and p = 0.4 (true y = 0). What is the Brier score?', ['0.1', '.1'], '(0.2² + 0.4²) / 2 = (0.04 + 0.16) / 2.'),
      mc('A false negative costs 20 and a false positive costs 1. With well-calibrated probabilities, the best threshold is about…', ['0.05 (1 / 21)', '0.5', '0.95', '0.2'], 'Flag whenever p × 20 > (1 - p) × 1, which means p > 1/21.')),

    L('Common mistakes and debugging',
      info('Metric traps', 'Most metric bugs are quiet: the code runs and the number looks plausible.\n\nThe usual suspects are swapped arguments, hard labels where scores are needed, thresholds tuned on the test set, and resampling done before the split.'),
      mc('A report says "precision 0.30, recall 0.90" but you expected the reverse. What bug fits this code?', ['The arguments are swapped, so the call returns recall', 'precision_score cannot take labels', 'It needs a threshold', 'There is no bug'], 'The signature is (y_true, y_pred); swapping them exchanges precision and recall.', 'p = precision_score(y_pred, y_true)'),
      mc('This AUC looks oddly low (0.71) for a strong model. Why?', ['It uses hard 0/1 predictions instead of scores, so the ranking has only two levels', 'roc_auc_score only works on regression', 'The labels should be strings', 'The model is too large'], 'Pass predict_proba(X)[:, 1].', 'auc = roc_auc_score(y_test, model.predict(X_test))'),
      mc('You picked the threshold that maximises F1 on the test set and reported that F1. What is wrong?', ['The test score is optimistic because the threshold was fitted to it', 'F1 cannot be maximised', 'Thresholds must be 0.5', 'Nothing'], 'Choose the threshold on validation data and report once on the test set.'),
      mc('You oversample the minority class with SMOTE and then split into train and test. What goes wrong?', ['Near-copies of training rows land in the test set and inflate the score', 'The classes become balanced in the test set, which is correct', 'The model underfits', 'Nothing, resampling is always safe'], 'Resample only the training folds.'),
      tf('A negative R² on the test set means the model is worse than always predicting the training mean.', true, 'R² of 0 equals the mean baseline.'),
      fill('roc_auc_score needs probability ___, not hard class labels.', ['scores', 'bins', 'folds', 'epochs'], 'It ranks the examples by score.'),
      info('Small numbers and odd targets', 'A precision of 100% on **3** predictions tells you almost nothing: put an interval around it.\n\n**MAPE** divides by the true value, so it explodes when actual values are near zero. Use MAE or a scaled error instead.'),
      tf('MAPE is a safe choice when the true values can be zero.', false, 'Dividing by zero (or near it) makes the metric infinite or huge.'),
      order('Investigating a suspiciously high AUC of 0.99', ['Check whether any feature is the label or is computed after the outcome', 'Look for duplicate rows across train and test', 'Check that preprocessing was fitted on training data only', 'Compare with a simple baseline', 'Re-run with a split that matches real use'], 'Rule out leakage before you trust the number.')),

    L('Case study: fraud detection with limited reviewers',
      info('The situation', 'A payment company processes **1,000,000** transactions a day. About **0.1%** are fraud: roughly **1,000** a day. A team of reviewers can check **500** flagged transactions a day. Each fraud that slips through costs **200**, and a review costs **2**.'),
      type('A model that always predicts "not fraud" has what accuracy, in percent?', ['99.9', '99.9%'], '999,000 correct out of 1,000,000.'),
      mc('Which pair of metrics matches how the model will be used?', ['Precision and recall within the top 500 scored transactions each day', 'Accuracy and R²', 'Training loss and epochs', 'RMSE and MAE'], 'Only the top 500 are reviewed.'),
      type('On a test day the top 500 contain 300 real frauds. What is the precision in percent?', ['60', '60%'], '300 / 500.'),
      type('On that same day there were 1,000 frauds. What is the recall of the top 500, in percent?', ['30', '30%'], '300 / 1,000.'),
      info('Capacity sets the threshold', 'Here the threshold is not 0.5. You rank by score and review the top 500, so the threshold moves with the volume of the day.\n\nA second model can handle the rest automatically: for example, block only the very highest scores and send the middle band to people.'),
      type('Those 300 caught frauds are each worth 200 saved, and 500 reviews cost 2 each. What is the net benefit for the day?', ['59000', '59,000'], '300 × 200 = 60,000, minus 500 × 2 = 1,000.'),
      mc('Labels arrive as chargebacks 30 to 60 days after a transaction. How should you train?', ['Use older data with complete labels and treat the newest weeks as not yet labelled', 'Treat every unlabelled transaction as not fraud', 'Train on the newest days only', 'Ignore chargebacks'], 'Missing labels are not negatives; unlabelled recent data would teach the model that fraud is rare.'),
      mc('Fraudsters change tactics after you launch. What is the best response?', ['Monitor precision and score distributions, retrain often, and keep a human feedback loop', 'Freeze the model for a year', 'Remove the reviewers', 'Raise the threshold to 0.99'], 'The problem is adversarial and moves.'),
      order('Order the project', ['Define fraud and the label delay', 'Split by time and build features known at transaction time', 'Train a baseline, then boosted trees', 'Evaluate precision and recall at 500 per day and net benefit', 'Launch with monitoring and a retraining schedule'], 'Capacity and cost decide what good means.')),

    L('Interview drill: metrics',
      info('Answering metric questions', 'Start with **what each error costs**, then the **class balance**, then name a metric and a threshold. Interviewers listen for the reasoning, not for a favourite metric.'),
      mc('"Why can a model with AUC 0.95 be useless for fraud review?"', ['AUC averages over all thresholds, but only the top few scores are reviewed, where precision may be low', 'AUC is always misleading', 'AUC measures accuracy', 'Fraud has no scores'], 'Evaluate at the operating point.'),
      mc('"How would you handle a 1% positive class?"', ['Choose metrics first (PR curve, recall at a precision), then class weights or resampling inside training folds, and tune the threshold', 'Delete negatives until balanced, then report accuracy', 'Always use SMOTE before splitting', 'Ignore it'], 'Metrics and costs come before tricks.'),
      mc('Follow-up: "Would you oversample before or after splitting?"', ['After: only the training folds are resampled', 'Before, so both sets are balanced', 'Never split', 'Only the test set'], 'Otherwise copies leak across the split.'),
      match('Match the situation to a sensible metric', [['Rare disease screening', 'Recall at a fixed precision'], ['Ranking search results', 'NDCG'], ['Forecast with big outliers', 'MAE'], ['Probabilities used to price risk', 'Log-loss and calibration']]),
      type('Precision 0.9 and recall 0.6. What is F1?', ['0.72', '.72'], '2 × 0.9 × 0.6 / (0.9 + 0.6) = 1.08 / 1.5.'),
      info('Expect the follow-up', 'Whatever you pick, the next question is usually "and what if the costs change?" or "how would you check that offline matches online?". Keep one sentence ready for each.'),
      tf('F1 is always the right metric for imbalanced data.', false, 'It ignores true negatives and treats both errors as equally costly.'),
      fill('To choose a threshold, weigh the ___ of each type of error on a validation set.', ['cost', 'depth', 'size', 'name'], 'Costs decide the operating point.'),
      order('Order a strong answer to "How would you evaluate a fraud model?"', ['Ask about the cost of a miss and of a false alarm', 'Note the class imbalance and choose precision and recall at the review capacity', 'Split by time to avoid leakage', 'Pick the threshold on validation data and report once on the test set', 'Plan an online test and monitoring'], 'Costs, imbalance, split, threshold, then production.'))
  ],

  'linear-models': [
    L('Fitting a line',
      info('The simplest model', 'Predict a number as a weighted sum of the inputs:\n\n```\ny_hat = w · x + b\n```\n\n`w` (weight) is the slope: how much y changes when x rises by one. `b` (bias) is the value when x is zero.'),
      type('w = 2, b = 1. What does the model predict for x = 3?', ['7'], '2 × 3 + 1.'),
      mc('In "price = 3000 × area + 50000", what does 3000 mean?', ['Each extra square metre adds 3000 to the price', 'The price of the smallest flat', 'The error', 'The number of flats'], 'The weight is the effect of one unit of the feature.'),
      info('How wrong is it?', 'We need one number for "how bad are these predictions". The usual choice is **mean squared error**:\n\n```\nMSE = mean((y_hat - y)²)\n```\n\nSquaring makes all errors positive and punishes large ones. Training means finding the `w` and `b` with the smallest loss.'),
      type('Predictions 3 and 5, true values 1 and 5. What is the MSE?', ['2', '2.0'], '(2² + 0²) / 2.'),
      mc('What does "training" a linear model mean?', ['Finding the weights that minimise the loss', 'Choosing the features', 'Collecting data', 'Plotting the line'], 'An optimisation problem.'),
      fillc('pred = X @ w + ___', ['b', 'y', 'X', 'lr'], 'Weighted sum plus bias.'),
      tf('With several features, a linear model has one weight per feature.', true, 'Plus one bias.')),

    L('Gradient descent',
      info('Walking downhill', 'Picture the loss as a landscape over all possible weights. **Gradient descent** starts anywhere and repeatedly takes a step **downhill**.\n\nThe **gradient** points uphill, so we move the opposite way:\n\n```\nw = w - learning_rate × gradient\n```'),
      type('w = 5, gradient = 2, learning rate = 0.1. What is the new w?', ['4.8'], '5 - 0.1 × 2.'),
      mc('The learning rate is far too large. What happens?', ['The loss bounces around or grows', 'Training is merely slow', 'The model becomes linear', 'Nothing'], 'Each step overshoots the minimum.'),
      mc('The learning rate is far too small. What happens?', ['Training crawls', 'The loss explodes', 'The weights become NaN', 'It converges instantly'], 'Tiny steps.'),
      order('One step of gradient descent for linear regression', ['pred = X @ w + b', 'err = pred - y', 'grad_w = (2 / n) * X.T @ err', 'w = w - lr * grad_w'], 'Predict, measure the error, compute the gradient, step.'),
      match('Match the variant', [['Batch', 'All data for every step'], ['Stochastic', 'One example per step'], ['Mini-batch', 'A small group per step'], ['Epoch', 'One full pass over the data']]),
      mc('Why scale features before gradient descent?', ['It makes the loss surface rounder, so training converges faster', 'It changes the best possible fit', 'It removes outliers', 'It is only cosmetic'], 'Unscaled features force a tiny learning rate.'),
      tf('For linear regression with MSE, the loss surface has a single minimum.', true, 'It is convex, so gradient descent cannot get stuck in a worse valley.')),

    L('Logistic regression',
      info('From numbers to probabilities', 'For yes/no questions we want a probability. Take the linear score and squash it with the **sigmoid**:\n\n```\np = 1 / (1 + e^(-z)),   z = w·x + b\n```\n\nLarge positive z gives p near 1; large negative z gives p near 0; z = 0 gives 0.5.'),
      type('What does the sigmoid output for z = 0?', ['0.5', '.5'], '1 / (1 + 1).'),
      mc('Despite its name, logistic regression is used for…', ['Classification', 'Regression', 'Clustering', 'Ranking only'], 'It outputs the probability of a class.'),
      info('Log-loss', 'The loss for probabilities is **log-loss** (cross-entropy). It punishes confident wrong answers heavily: predicting 0.99 for something false costs far more than predicting 0.6.\n\nThe gradient has the same shape as before: `X.T @ (p - y) / n`.'),
      mc('The true label is 1. Which prediction gets the largest log-loss?', ['0.01', '0.4', '0.6', '0.99'], 'Confident and wrong.'),
      mc('A coefficient of 0.7 on a feature means…', ['One more unit raises the log-odds by 0.7', 'The probability rises by 0.7', 'The feature is 70% important', 'Accuracy is 70%'], 'exp(0.7) ≈ 2: the odds double.'),
      mc('The decision boundary of logistic regression is…', ['A straight line (a hyperplane)', 'A circle', 'A staircase', 'Random'], 'It is linear in the features. Add interactions or use another model for curved boundaries.'),
      tf('Logistic regression is a strong, interpretable baseline for classification.', true, 'Always try it before something heavier.')),

    L('Regularisation and interview level',
      info('Ridge and lasso', 'Add a penalty on the size of the weights:\n\n- **Ridge (L2):** `λ · sum(w²)`. Shrinks weights; handles correlated features well.\n- **Lasso (L1):** `λ · sum(|w|)`. Sets some weights to zero.\n\n`λ` is tuned by cross-validation. Scale features first.'),
      mc('Two features are almost identical. Which model stays stable?', ['Ridge', 'Unregularised least squares', 'Neither', 'Both equally'], 'Without a penalty, the weights can become huge with opposite signs.'),
      mc('You have 5,000 features and suspect only 30 matter. Try…', ['Lasso', 'Ridge', 'No regularisation', 'A larger learning rate'], 'L1 performs feature selection.'),
      match('Match the assumption to its check', [['Linearity', 'Residuals against predictions show no curve'], ['Constant variance', 'Residual spread does not fan out'], ['Independent errors', 'No pattern over time'], ['No multicollinearity', 'Features are not strongly correlated']]),
      mc('Residuals fan out as predictions grow. A common remedy?', ['Model the log of the target', 'Add more epochs', 'Remove the bias', 'Shuffle the data'], 'A log transform often stabilises variance.'),
      order('Order: implement logistic regression from scratch', ['Initialise weights to zero', 'Compute p = sigmoid(X @ w + b)', 'Compute the gradient X.T @ (p - y) / n', 'Update w and b', 'Repeat until the loss stops improving'], 'A very common interview task.'),
      mc('Why not use MSE as the loss for logistic regression?', ['It becomes non-convex and gives weak gradients for confident mistakes', 'It is illegal', 'It cannot be computed', 'It is identical to log-loss'], 'Log-loss is convex here and matches maximum likelihood.'),
      mc('When would you prefer a linear model over a neural network?', ['Little data, need for interpretability, or a fast baseline', 'Never', 'Only for images', 'When you have a GPU'], 'Simplicity is a feature.'),
      tf('The closed-form solution of linear regression always scales better than gradient descent.', false, 'It needs a matrix inverse, which is costly with many features.')),

    L('Deeper linear models: R², odds and softmax',
      info('Still linear', 'A model is **linear** when it is linear in its **weights**, not in the raw input. Adding `x²` as a new column gives a curved fit that is still a linear model.\n\n**R²** compares your errors with the errors of always predicting the mean:\n\n```\nR² = 1 - SSE / SST\n```\n\nSSE is the sum of squared model errors, SST the sum of squared distances from the mean.'),
      type('SSE = 20 and SST = 100. What is R²?', ['0.8', '.8', '80%'], '1 - 20/100.'),
      mc('You add the column x² to a linear regression. Is it still a linear model?', ['Yes: it is linear in the weights', 'No: any square makes it non-linear', 'Only if x is positive', 'Only with regularisation'], 'The weights still multiply the columns and add up.'),
      mc('The closed-form (normal equation) solution needs to invert a matrix whose size is…', ['Number of features × number of features', 'Rows × rows', 'Rows × features', 'One by one'], 'Cost grows quickly with the number of features, which is why gradient descent is used at scale.'),
      info('Odds and more than two classes', '**Odds** = p / (1 - p). The **log-odds** is what the linear part of logistic regression predicts, so a weight adds to the log-odds.\n\nFor more than two classes use **softmax**, which turns scores into probabilities that sum to 1:\n\n```\nsoftmax(z_i) = e^(z_i) / sum(e^(z_j))\n```'),
      type('A probability of 0.8 corresponds to odds of…', ['4', '4.0', '4:1'], '0.8 / 0.2.'),
      type('Softmax over three equal scores [1, 1, 1]. What is the probability of the first class?', ['0.33', '0.333', '.33', '.333', '1/3'], 'Three equal shares of 1.'),
      mc('Elastic net adds both an L1 and an L2 penalty. When is that attractive?', ['Many correlated features where you still want some weights to reach zero', 'You want no regularisation', 'The target is a category with 500 levels', 'You have fewer features than rows and no noise'], 'L2 handles correlation, L1 gives sparsity.'),
      mc('Logistic regression is trained without regularisation on data that a line separates perfectly. What happens to the weights?', ['They keep growing without bound as training continues', 'They settle at zero', 'They become negative', 'Training fails at once'], 'The loss can always be lowered by making the boundary sharper; regularisation fixes it.')),

    L('Common mistakes and debugging',
      info('Linear models fail quietly', 'A linear model almost never crashes. It just gives bad numbers, and the cause is usually in the **data** or the **gradient code**.\n\nWhen the loss does something odd, check the sign of the update, the shapes of the arrays and the scale of the features.'),
      mc('The loss grows every step. What is the bug in this update?', ['The gradient is added instead of subtracted, so each step goes uphill', 'The learning rate is zero', 'There is no bias', 'The data is too small'], 'Gradient descent subtracts the gradient.', 'grad_w = (2 / n) * X.T @ err\nw = w + lr * grad_w'),
      mc('What is wrong with this gradient?', ['X is not transposed, so the shapes do not give one gradient per feature', 'err should be squared again', 'n should be 1', 'It needs a sigmoid'], 'X.T @ err sums error times feature over all rows, one value per weight.', 'err = X @ w + b - y          # shape (n,)\ngrad_w = (2 / n) * X @ err'),
      mc('A model is evaluated like this. What is the bug?', ['The test features are scaled with their own mean and spread instead of the training ones', 'fit_transform is slower than fit', 'The scaler needs a seed', 'Nothing'], 'Fit the scaler on training data and only transform the test data.', 'X_train = scaler.fit_transform(X_train)\nX_test = scaler.fit_transform(X_test)'),
      mc('LogisticRegression warns that it did not converge with raw features of very different scales. A good first fix?', ['Standardise the features, then raise max_iter if needed', 'Delete the warning', 'Use fewer rows', 'Switch to a regression metric'], 'Poorly scaled features make the optimisation slow.'),
      fill('If the loss rises or bounces at every step, the learning rate is probably too ___.', ['large', 'small', 'exact', 'discrete'], 'Steps overshoot the minimum.'),
      info('Traps in the data', '- **Dummy-variable trap:** one-hot encoding every category and keeping an intercept makes the columns add to one, so the weights are not unique. Drop one level, or use a penalty.\n- **Outliers** have a large pull on least squares because errors are squared.\n- A **curved residual plot** means a missing non-linear term.'),
      mc('You one-hot encode all 4 cities and also fit an intercept with plain least squares. What is the problem?', ['The four columns always sum to 1, so the solution is not unique', 'The model becomes non-linear', 'The loss is no longer convex', 'The weights become zero'], 'Drop one category, for example drop="first".'),
      tf('A single extreme outlier can noticeably tilt a least-squares line.', true, 'Squaring makes large errors dominate; use a robust loss such as Huber if needed.'),
      mc('Adding a second, highly correlated feature flips the sign of the first feature’s weight. Why?', ['Multicollinearity: the model splits the shared signal unpredictably between them', 'The first feature became irrelevant', 'The learning rate changed', 'Logistic regression is non-linear'], 'Correlated features make individual weights unstable.')),

    L('Case study: predicting delivery time',
      info('The situation', 'A food-delivery app wants to show an estimated delivery time. Always predicting the average gives a mean absolute error (MAE) of **12 minutes**. You start with a **linear regression** on distance, hour and weather. It is fast, explainable to the operations team and easy to debug.'),
      mc('Step 1: which target and baseline do you use?', ['Delivery minutes, compared with always predicting the training average', 'Whether the order was late, compared with accuracy', 'Distance, compared with weather', 'Order value, compared with time'], 'A model is only useful if it beats the simplest guess.'),
      type('Step 2: after fitting, time = 5 + 3.2 × km. What is the prediction for a 4 km trip, in minutes?', ['17.8'], '5 + 3.2 × 4.'),
      type('Step 3: that trip really took 22 minutes. What is the residual (actual minus predicted)?', ['4.2'], '22 - 17.8.'),
      mc('Step 4: the model’s MAE is 6 minutes, against 12 for the baseline. What do you report?', ['The error is halved against the baseline, measured on later data it never saw', 'The model is perfect', 'R² must be 1', 'MAE is meaningless'], 'Always quote the improvement over the baseline on held-out data.'),
      info('Look at the residuals', 'Plot residuals against predictions. If they **fan out** for long trips, the errors grow with the size of the trip, and a straight line is not enough: errors are better described in **percent**.\n\nThat is a classic signal to model the **log** of the target.'),
      mc('Step 5: residuals fan out for trips over 8 km. What do you try?', ['Model the log of the delivery time', 'Remove the distance feature', 'Delete all long trips', 'Predict the median for everyone'], 'A log target turns multiplicative errors into additive ones.'),
      mc('Step 6: customers hate late deliveries far more than early ones. How do you adapt?', ['Predict a higher quantile (or add a buffer) so that most orders arrive before the estimate', 'Always show the average', 'Hide the estimate', 'Minimise RMSE only'], 'Asymmetric costs call for an asymmetric prediction.'),
      mc('Step 7: boosted trees reach an MAE of 5.4 minutes against 6.0 for the linear model. What do you weigh?', ['A 10% gain against complexity, explainability and a check on a later period', 'Only the lower number', 'Only the model name', 'Nothing, linear is always better'], 'A small gain may not justify a harder model; verify it holds on newer data.'),
      order('Order the project', ['Define the target and the baseline', 'Fit a linear model on a few clear features', 'Check residuals and fix patterns', 'Compare with a stronger model on a later period', 'Ship with monitoring of errors by distance band'], 'Simple first, justify complexity.')),

    L('Interview drill: linear models',
      info('What interviewers listen for', 'Linear-model questions test whether you understand the **mechanics** (loss, gradient, penalty) and can explain them **in plain words**. Practise saying each answer in two sentences, then add the detail if asked.'),
      mc('"Why does L1 give exact zeros but L2 only small weights?"', ['L1 pulls every weight toward zero with constant force; L2’s pull weakens as the weight shrinks', 'L1 is faster', 'L2 ignores large weights', 'They behave identically'], 'The corner of the L1 constraint sits on the axes.'),
      mc('"Why not use linear regression for a 0/1 target?"', ['It can predict outside 0 to 1 and its errors are not suited to a yes/no outcome', 'It cannot be trained', 'It needs more data', 'It always overfits'], 'Logistic regression models a probability.'),
      mc('"A feature has 500 categories. How do you use it in a linear model?"', ['Group rare levels, or use target or frequency encoding inside the training folds, with regularisation', 'One-hot encode and use no regularisation', 'Use the category number', 'Drop the model'], 'Avoid 500 unstable columns, and avoid leakage in the encoding.'),
      type('Logistic regression has w = 2 and b = -1. For x = 0.5, what probability does it output?', ['0.5', '.5'], 'z = 2 × 0.5 - 1 = 0, and the sigmoid of 0 is 0.5.'),
      info('Know the follow-ups', '- "How do you know the assumptions hold?" → residual plots.\n- "What if features are correlated?" → ridge, or drop one.\n- "How would you speed it up on 100 million rows?" → mini-batch gradient descent.\n- "Can you explain a single prediction?" → weight × feature value.'),
      match('Match the question to what it tests', [['Derive the gradient of MSE', 'Calculus and shapes'], ['Why scale before ridge?', 'How the penalty treats units'], ['Why log-loss?', 'Probabilistic view and convexity'], ['Linear or boosted trees?', 'Judgement on trade-offs']]),
      fill('The closed-form solution of linear regression is called the normal ___.', ['equation', 'distribution', 'form', 'vector'], 'It solves X.T @ X w = X.T @ y.'),
      tf('Logistic regression with an L2 penalty has a single best set of weights.', true, 'The penalised loss is strictly convex.'),
      order('Order a strong answer to "Explain linear regression from scratch"', ['State the model: prediction is a weighted sum plus a bias', 'Define the loss: mean squared error', 'Describe fitting: gradient descent or the normal equation', 'Mention scaling and regularisation', 'Name the assumptions and how to check them'], 'Model, loss, fit, practicalities, checks.'))
  ],

  trees: [
    L('Decisions as questions',
      info('Twenty questions', 'A **decision tree** predicts by asking yes/no questions about the features, one after another:\n\n"Income above 30k?" → "Age under 25?" → predict.\n\nEach question is a **split**, the end points are **leaves**. It is easy to read and needs no feature scaling.'),
      match('Match the part', [['Root', 'The first question'], ['Split', 'A question on one feature'], ['Leaf', 'A final prediction'], ['Depth', 'Number of questions on the longest path']]),
      mc('What does a leaf of a classification tree predict?', ['The most common class among its training samples', 'A random class', 'The average feature value', 'Nothing'], 'A regression tree predicts the mean of the targets.'),
      tf('Decision trees need features to be scaled.', false, 'Splits compare a feature with a threshold; the scale does not matter.'),
      info('Which question is best?', 'The tree picks the split that makes the two sides as **pure** as possible. Purity is measured by **Gini impurity**:\n\n```\ngini = 1 - sum(p_class²)\n```\n\n0 means one class only. 0.5 is the worst for two classes.'),
      type('A node has 10 samples, all of class A. What is its Gini impurity?', ['0', '0.0'], '1 - 1².'),
      type('A node has 5 samples of class A and 5 of class B. What is its Gini impurity?', ['0.5', '.5'], '1 - (0.25 + 0.25).'),
      mc('Which split would a tree prefer?', ['One that separates the classes almost completely', 'One that leaves both sides mixed', 'One on the first column', 'A random one'], 'Largest reduction in impurity.')),

    L('Overfitting and forests',
      info('A tree can memorise', 'Grown without limits, a tree keeps splitting until every leaf holds one sample. It scores 100% on training data and poorly on new data.\n\nControls: `max_depth`, `min_samples_leaf`, pruning.'),
      mc('An unlimited-depth tree reaches 100% training accuracy. It has probably…', ['Overfitted', 'Underfitted', 'Found the truth', 'Leaked'], 'It memorised, including the noise.'),
      mc('Which setting makes a tree simpler?', ['Lower max_depth', 'Higher max_depth', 'Lower min_samples_leaf', 'More features'], 'Fewer questions, fewer leaves.'),
      info('Random forest', 'One tree is unstable. A **random forest** trains hundreds of trees, each on a **bootstrap sample** (rows drawn with replacement) and with a **random subset of features** at each split, then averages them.\n\nMany different, noisy trees average into a stable model. This is **bagging**.'),
      mc('Why does each tree see different rows and features?', ['So the trees make different errors that average out', 'To save disk space', 'To make them identical', 'To overfit more'], 'Averaging only helps if the models are not all the same.'),
      mc('A random forest mainly reduces…', ['Variance', 'Bias', 'Data size', 'The number of features'], 'Each deep tree has low bias and high variance.'),
      fill('Sampling rows with replacement to train each tree is called ___.', ['bootstrapping', 'boosting', 'pruning', 'stacking'], 'Bagging = bootstrap aggregating.'),
      tf('Adding more trees to a random forest eventually causes severe overfitting.', false, 'More trees stabilise the average; returns just diminish.')),

    L('Gradient boosting',
      info('Learning from mistakes', '**Boosting** builds trees **one after another**. Each new small tree is trained to fix the errors the ensemble still makes.\n\n```\nprediction = tree1 + lr·tree2 + lr·tree3 + …\n```\n\nLibraries: XGBoost, LightGBM, CatBoost. They dominate tabular problems.'),
      mc('What does each new tree in gradient boosting fit?', ['The residual errors of the current ensemble', 'The original target from scratch', 'Random noise', 'The test set'], 'More precisely, the negative gradient of the loss.'),
      match('Compare the two ensembles', [['Random forest', 'Trees built independently, then averaged'], ['Gradient boosting', 'Trees built in sequence, each correcting the last'], ['Forest reduces', 'Variance'], ['Boosting reduces', 'Bias']]),
      mc('A smaller learning rate in boosting needs…', ['More trees', 'Fewer trees', 'Deeper trees', 'No trees'], 'Smaller steps, more of them; usually generalises better.'),
      mc('How do you choose the number of trees?', ['Early stopping on a validation set', 'Always 100', 'As many as possible', 'One per feature'], 'Stop when validation error stops improving.'),
      mc('Your boosted model overfits. Which does NOT help?', ['Deeper trees', 'Lower learning rate with early stopping', 'Row and column subsampling', 'Stronger regularisation'], 'Deeper trees add capacity.'),
      tf('Gradient-boosted trees usually beat deep learning on small and medium tabular datasets.', true, 'They handle mixed features, missing values and irregular patterns well.'),
      mc('Boosting trees are typically…', ['Shallow (depth 3 to 8)', 'Extremely deep', 'A single leaf always', 'Unlimited'], 'Weak learners combined in sequence.')),

    L('Interpretation and interview level',
      info('Which features matter?', 'Built-in **split importance** is biased toward features with many distinct values.\n\nBetter: **permutation importance** (shuffle a feature, measure the drop in score) and **SHAP values** (each feature’s contribution to each prediction).'),
      mc('You shuffle one feature’s column and the score does not change. That feature is…', ['Not used meaningfully by the model', 'The most important', 'Leaking', 'Categorical'], 'That is permutation importance.'),
      mc('A customer-ID column shows the highest split importance. Why be suspicious?', ['High-cardinality features get inflated importance and invite memorisation', 'IDs are always predictive', 'Importance is never wrong', 'It proves causation'], 'Remove identifiers.'),
      mc('How do tree libraries such as XGBoost treat missing values?', ['They learn a default direction for them at each split', 'They crash', 'They delete the rows', 'They replace them with zero always'], 'So imputation is often unnecessary.'),
      order('Order a tuning plan for gradient boosting', ['Start with defaults and early stopping', 'Tune tree depth and minimum leaf size', 'Tune row and column subsampling', 'Lower the learning rate and add trees', 'Confirm on a held-out set'], 'Structure first, then shrinkage.'),
      mc('Why might you deploy a random forest instead of boosting on an embedded radar ECU?', ['Trees are independent, simple to convert to C, and robust with little tuning', 'It is always more accurate', 'Boosting cannot be converted', 'Forests use no memory'], 'Either can be generated as nested if/else; size and timing decide.'),
      mc('Interviewer: "Explain the difference between bagging and boosting in one sentence."', ['Bagging averages independent models to cut variance; boosting adds models in sequence to cut bias', 'They are the same', 'Bagging is for images, boosting for text', 'Boosting uses bigger trees'], 'Know this cold.'),
      tf('Feature importance tells you that a feature causes the outcome.', false, 'It shows what the model uses, not causation.'),
      mc('Which model would you try first on a 50,000-row table with mixed numeric and categorical features?', ['Gradient-boosted trees', 'A convolutional network', 'A transformer trained from scratch', 'k-means'], 'The standard strong baseline.')),

    L('Deeper trees: entropy, splits and out-of-bag',
      info('Measuring impurity', 'Gini is not the only measure. **Entropy** is `-sum(p × log2(p))`: 0 for a pure node and 1 bit for a 50/50 split of two classes.\n\nA split is scored by the **weighted** impurity of its two children: each child counts in proportion to its share of the samples.'),
      type('What is the entropy, in bits, of a node with 5 samples of class A and 5 of class B?', ['1', '1.0'], '-(0.5 × log2 0.5 + 0.5 × log2 0.5) = 1.'),
      type('A node is 80% class A and 20% class B. What is its Gini impurity?', ['0.32', '.32'], '1 - (0.64 + 0.04).'),
      type('A split sends 6 samples to a pure left child (Gini 0) and 4 samples to a right child with Gini 0.5. What is the weighted Gini?', ['0.2', '.2'], '0.6 × 0 + 0.4 × 0.5.'),
      info('Free validation and regression trees', 'Each bootstrap sample leaves out about **37%** of the rows (1/e). Those **out-of-bag** rows act as a free validation set for every tree.\n\nA **regression tree** chooses splits that reduce the **variance** (squared error) of the target and predicts the mean of the leaf.'),
      type('To the nearest whole percent, how many rows are left out of a bootstrap sample of the same size as the data?', ['37', '37%'], 'About 1/e of the rows.'),
      mc('A regression tree chooses a split by…', ['The largest reduction in squared error', 'The highest Gini', 'The lowest number of rows', 'Random choice'], 'It wants leaves with similar target values.'),
      mc('You lower max_features in a random forest. What is the main effect?', ['The trees become more different from each other, so averaging cancels more variance', 'The trees become identical', 'Bias drops sharply', 'Training becomes impossible'], 'Decorrelated trees average better, at a small cost in bias.'),
      mc('The largest flat in the training data is 250 m². You predict the price of a 400 m² flat with a tree-based model. What do you get?', ['About the same price as the largest training flats: trees cannot extrapolate', 'A price that continues the trend', 'An error', 'A negative price'], 'A tree predicts the mean of a leaf, so it stays inside the range it has seen.')),

    L('Common mistakes and debugging',
      info('Tree models hide their mistakes well', 'They accept raw data, missing values and any scale, so bugs rarely cause errors. The warnings are quieter: **too-good scores**, **unstable results**, and **performance that vanishes in production**.'),
      mc('What is wrong with this training call?', ['The early-stopping set is the test set, so the test score is no longer independent', 'early_stopping_rounds is not allowed', 'eval_set must be empty', 'There is no learning rate'], 'Use a separate validation set for stopping.', 'model.fit(X_train, y_train,\n          eval_set=[(X_test, y_test)],\n          early_stopping_rounds=20)'),
      mc('This code gives an error at prediction time. Why?', ['get_dummies on each set can create different columns when a category is missing from one', 'get_dummies cannot handle strings', 'The test set is too small', 'pandas forbids two calls'], 'Fit one encoder on training data and reuse it, or align the columns.', 'X_train = pd.get_dummies(train_df)\nX_test = pd.get_dummies(test_df)\nmodel.predict(X_test)'),
      mc('A classifier on a 99% / 1% problem predicts the majority class for every row. First fix to try?', ['class_weight="balanced" (or scale_pos_weight) and a tuned threshold', 'More depth only', 'Remove the minority class', 'Standardise the features'], 'The default loss lets the majority dominate.'),
      fill('Results change on every run of a random forest unless you fix the random ___.', ['state', 'depth', 'leaf', 'weight'], 'In scikit-learn it is random_state.'),
      tf('Standardising the features before a decision tree changes which splits it finds.', false, 'Scaling preserves the order of values, so the same splits exist.'),
      info('Time and drift', 'A tree cannot extrapolate a **trend**. If the target grows over time, a model trained on last year will under-predict this year. Predict the **change** or a ratio, or add trend features.\n\nAlso check **feature order and names**: a model that expects 40 columns in a fixed order breaks silently when they are shuffled.'),
      mc('Sales grow 10% a year. A forest trained on 2022 to 2024 predicts 2026 too low. Why?', ['Leaves hold values from the past and cannot continue a trend', 'The forest is too deep', 'The test set leaked', 'Trees need scaling'], 'Model the growth rate, or detrend the target.'),
      mc('A model with max_depth=2 scores 0.71 on training and 0.70 on validation. What do you try?', ['Deeper trees or better features: it underfits', 'More regularisation', 'Early stopping', 'Fewer features'], 'Both scores are low and close.'),
      order('Debugging a boosted model that overfits', ['Plot training and validation loss per tree', 'Enable early stopping on a validation set', 'Lower the learning rate and use shallower trees', 'Add row and column subsampling', 'Re-check with cross-validation'], 'Diagnose with curves first.')),

    L('Case study: predicting machine failures',
      info('The situation', 'A factory has **5,000 machines** with sensors. About **2%** fail in a given week, so roughly **100** unplanned breakdowns. The maintenance crew can inspect **150** machines per week. An unplanned failure costs **10,000**, an inspection costs **200**, and we assume an inspection prevents the failure.'),
      mc('Step 1: what is one training row?', ['A machine-week, with features from before the week and a label for failure during it', 'A single sensor reading with the machine’s lifetime label', 'A whole machine with its final failure date', 'A week of the factory as one number'], 'Fix the prediction moment, then label what happens next.'),
      type('Step 2: how many machines are expected to fail in a typical week?', ['100'], '2% of 5,000.'),
      mc('Step 3: how should you split the data?', ['By time, so the test weeks come after all training weeks', 'Random rows', 'Train on one machine, test on another', 'Use the test weeks for tuning'], 'Predictions are always about the future.'),
      info('Features from sensors', 'Raw readings are noisy. Useful features are **rolling statistics over the past days** (mean, maximum, slope), **time since the last maintenance**, and **how far a reading is from that machine’s normal**. Every window must end **before** the prediction moment.'),
      mc('Step 4: which feature is leakage?', ['Whether a repair ticket was opened this week', 'Mean temperature over the last 7 days', 'Days since last maintenance', 'Machine model'], 'Tickets are raised because the machine failed.'),
      type('Step 5: the model’s top 150 machines contain 60 of the 100 that fail. What is the precision, in percent?', ['40', '40%'], '60 / 150.'),
      type('Step 6: what is the recall of that list, in percent?', ['60', '60%'], '60 / 100.'),
      type('Step 7: what is the weekly net benefit of inspecting those 150 machines?', ['570000', '570,000'], '60 × 10,000 = 600,000 saved, minus 150 × 200 = 30,000.'),
      mc('Step 8: permutation importance shows the rolling temperature slope matters most. What do you do with it?', ['Check with engineers that it makes physical sense and use it to guide inspections', 'Claim that temperature causes failures', 'Delete the feature', 'Ignore it'], 'Importance shows what the model uses, and a domain expert can confirm whether it is plausible.'),
      order('Order the project', ['Define the machine-week row and the label', 'Build rolling features that end before the prediction time', 'Split by time and train boosted trees', 'Measure precision, recall and net benefit at 150 inspections', 'Pilot with the crew and monitor drift'], 'Define, build, validate on time, then pilot.')),

    L('Interview drill: trees and ensembles',
      info('What interviewers look for', 'Tree questions test whether you can explain **why** the models behave as they do, not only which library to call. Expect "why", then "what would you change?".'),
      mc('"Why does a random forest overfit less than a single deep tree?"', ['Averaging many decorrelated trees cancels their individual errors, which cuts variance', 'It uses shallower trees only', 'It sees more features at once', 'It trains for longer'], 'Variance falls; bias stays about the same.'),
      mc('Follow-up: "Can adding more trees hurt a random forest?"', ['Not accuracy in practice, but it adds size and prediction time', 'Yes, it always overfits', 'Yes, it raises bias', 'It makes the trees identical'], 'The error plateaus; cost keeps growing.'),
      match('Match the boosting hyperparameter to its effect', [['max_depth', 'Complexity of each tree'], ['learning_rate', 'How much each tree contributes'], ['subsample', 'Share of rows used per tree'], ['min_child_weight', 'Smallest amount of data a leaf may hold']]),
      type('A forest of 200 trees: 130 vote for class A. What fraction of votes does A get?', ['0.65', '.65', '65%'], '130 / 200. Many libraries report this as the probability.'),
      info('Follow-ups to prepare', '- "How do you tune it?" → defaults, early stopping, depth, subsampling, then lower the learning rate.\n- "How do you explain it?" → permutation importance and SHAP.\n- "It is too slow in production" → fewer and shallower trees, quantisation, or distillation.\n- "When would you not use trees?" → images, text, extrapolation.'),
      mc('"The boosted model is accurate but too slow for a 10 ms limit." First options?', ['Fewer or shallower trees, a faster library or a distilled smaller model', 'Add more trees', 'Remove the validation set', 'Use a bigger server only'], 'Trade a little accuracy for latency.'),
      tf('A tree-based model can predict values far outside the range of its training targets.', false, 'Leaves hold averages of seen values.'),
      fill('Gini impurity and ___ are two ways to measure how mixed a node is.', ['entropy', 'accuracy', 'recall', 'bias'], 'Both are zero for a pure node.'),
      order('Order a strong answer to "Walk me through how a decision tree is built"', ['Start with all samples at the root', 'Try every feature and threshold and score the weighted impurity', 'Take the best split and divide the samples', 'Repeat on each child until a stopping rule is met', 'Predict the majority class or mean in each leaf and prune or limit depth'], 'Greedy, recursive, stopped by rules.'))
  ],

  'feature-eng': [
    L('Meet the DataFrame',
      info('Tables in Python', '**pandas** holds data in a **DataFrame**: a table with named columns.\n\n```python\nimport pandas as pd\ndf = pd.read_csv("orders.csv")\ndf.head()          # first rows\ndf.info()          # types and missing values\ndf.describe()      # summary statistics\n```'),
      match('Match the call to what it shows', [['df.head()', 'The first few rows'], ['df.shape', 'Number of rows and columns'], ['df.info()', 'Column types and non-null counts'], ['df.describe()', 'Mean, min, max and quartiles']]),
      fillc('adults = df[df["age"] ___ 18]', ['>=', '=>', 'is', 'in'], 'A boolean condition selects rows.'),
      mc('How do you select one column as a Series?', ['df["price"]', 'df("price")', 'df.price()', 'df{price}'], 'Square brackets with the column name.'),
      fillc('df["total"] = df["price"] ___ df["quantity"]', ['*', '@', 'x', 'times'], 'Operations apply to whole columns at once.'),
      mc('Why avoid looping over DataFrame rows with a for loop?', ['Vectorised column operations are far faster', 'It is forbidden', 'It changes the data', 'Loops cannot read floats'], 'Let pandas work on whole columns.'),
      tf('`df.isna().sum()` counts missing values per column.', true, 'A first step in every data-quality check.'),
      mc('`df.sort_values("price", ascending=False).head(3)` returns…', ['The three most expensive rows', 'The three cheapest rows', 'Three random rows', 'The column names'], 'Sort descending, take the top.')),

    L('Group, join and reshape',
      info('Split, apply, combine', '`groupby` splits rows into groups, computes something per group, and combines the results:\n\n```python\ndf.groupby("user_id")["amount"].agg(n="count", total="sum", avg="mean")\n```\n\n`merge` joins two tables, like SQL.'),
      order('Per-user order statistics', ['out = df.groupby("user_id")["amount"]', 'out = out.agg(n_orders="count", total="sum")', 'out = out.reset_index()', 'out = out.sort_values("user_id")'], 'reset_index turns the group key back into a column.'),
      mc('`df.groupby("city")["price"].mean()` gives…', ['The average price for each city', 'One overall average', 'The number of cities', 'The prices sorted'], 'One value per group.'),
      fillc('orders.merge(users, on="user_id", how="___")   # keep every order', ['left', 'inner', 'right', 'cross'], 'A left join keeps all rows of the left table.'),
      mc('After a merge the row count doubled unexpectedly. Likely cause?', ['Duplicate keys in the other table', 'Too many columns', 'Missing values', 'Wrong dtype'], 'Check key uniqueness before merging.'),
      fillc('df["month"] = pd.to_datetime(df["ts"]).___.month', ['dt', 'date', 'time', 'str'], 'The .dt accessor exposes date parts.'),
      mc('A rolling 7-day mean used to predict today must…', ['Exclude today (shift by one)', 'Include today', 'Include next week', 'Be sorted randomly'], 'Otherwise the feature leaks the target.'),
      tf('`pivot_table` turns long data into a wide table with one column per category.', true, 'Useful for features such as "spend per category".')),

    L('Missing values, categories and scales',
      info('Missing data', 'First ask **why** it is missing; that is often a signal.\n\nOptions: drop the rows (if few), fill with the **median** or the **mode**, and add a column `was_missing`.\n\nFit the imputer on the training data only.'),
      mc('Income is skewed and 15% missing. Sensible approach?', ['Fill with the median and add a "was missing" flag', 'Fill with zero', 'Delete the column', 'Fill with the maximum'], 'The median resists the skew; the flag keeps the signal.'),
      info('Categories', 'Models need numbers.\n\n- **One-hot:** one 0/1 column per category. Fine for a few categories.\n- **Ordinal:** integers, when there is a real order (S < M < L).\n- **Target / frequency encoding:** for hundreds or thousands of categories.'),
      mc('Encode "city" with 4 possible values for a linear model. Use…', ['One-hot encoding', 'Integers 1 to 4', 'The city name length', 'Nothing'], 'Integers would invent an order and distances.'),
      mc('Encode "product_id" with 80,000 values. Use…', ['Target or frequency encoding, or embeddings', 'One-hot encoding', 'Drop every row', 'Ordinal by alphabet'], 'One-hot would create 80,000 sparse columns.'),
      mc('Target encoding computed on the whole dataset before splitting causes…', ['Leakage of the label into the features', 'Underfitting', 'Faster training only', 'Nothing'], 'Compute it inside each training fold.'),
      match('Match the model to its scaling need', [['k-nearest neighbours', 'Needs scaling'], ['Neural network', 'Needs scaling to train well'], ['Gradient-boosted trees', 'No scaling needed'], ['Linear model with L2', 'Scale so the penalty is fair']]),
      mc('A right-skewed feature such as income is often improved by…', ['A log transform', 'Squaring it', 'One-hot encoding', 'Reversing it'], 'It compresses the long tail.')),

    L('Feature ideas and interview level',
      info('Features that usually help', '- **Aggregates per entity:** count, sum, mean, max.\n- **Recency:** days since last purchase.\n- **Ratios and changes:** this week against the last month.\n- **Time parts:** hour, weekday, holiday.\n- **Interactions:** price per square metre.'),
      mc('Which is a recency feature?', ['Days since the customer’s last order', 'Total number of orders', 'Customer’s city', 'Average order value'], 'How recently something happened.'),
      mc('To predict churn today you use "number of support tickets next month". This is…', ['Leakage: the future is not known today', 'A great feature', 'A recency feature', 'Regularisation'], 'Only use what is known at prediction time.'),
      order('Order a feature-engineering workflow', ['Understand the prediction moment and what is known then', 'Build a baseline with raw features', 'Add candidate features one group at a time', 'Validate each with cross-validation', 'Keep what helps, drop the rest'], 'Measure every addition.'),
      mc('Feature selection with a statistical test (chi-square, ANOVA, mutual information) is a…', ['Filter method', 'Wrapper method', 'Embedded method', 'Clustering method'], 'It scores features independently of the model. Lasso is embedded; recursive elimination is a wrapper.'),
      mc('Why can too many features hurt?', ['More noise to overfit, slower training, harder maintenance', 'Models cannot read them', 'They increase bias', 'They always help'], 'The curse of dimensionality.'),
      mc('Interviewer: "How do you handle outliers?"', ['First check whether they are errors or real; then clip, transform or use a robust model', 'Always delete them', 'Always keep them', 'Replace them with zero'], 'In fraud or fault detection the outliers are the point.'),
      mc('Which statement about feature stores is right?', ['They serve the same feature definitions for training and for live prediction', 'They store model weights', 'They replace databases', 'They are a kind of GPU'], 'They prevent training-serving skew.'),
      tf('Good features often beat a more complex model on tabular data.', true, 'Domain knowledge encoded as features is hard to learn from little data.')),

    L('Deeper features: scaling, cycles and smoothing',
      info('Choosing a scaler', '- **StandardScaler:** subtract the mean, divide by the standard deviation.\n- **MinMaxScaler:** map to 0 to 1: `(x - min) / (max - min)`.\n- **RobustScaler:** use the median and the interquartile range, so outliers matter less.\n- **Log transform:** compresses a long right tail.\n\nFor **cyclic** values such as hour of day, use `sin` and `cos` of the angle, so 23:00 and 00:00 end up next to each other.'),
      type('Min-max scaling with min 10 and max 50. What is the scaled value of 30?', ['0.5', '.5'], '(30 - 10) / (50 - 10).'),
      match('Match the transformation to its use', [['StandardScaler', 'Mean 0 and standard deviation 1'], ['MinMaxScaler', 'Values squeezed into 0 to 1'], ['RobustScaler', 'Outliers have little influence'], ['Log transform', 'Compress a long right tail']]),
      mc('Hour of day is stored as 0 to 23. Why does the raw number mislead a linear model?', ['23 and 0 are far apart as numbers but adjacent on the clock', 'Hours are too large', 'Hours are always categorical', 'It cannot be scaled'], 'Encode with sin and cos of 2π × hour / 24.'),
      mc('Which scaler suits a column with a few extreme outliers?', ['RobustScaler', 'MinMaxScaler', 'None of them can be used', 'One-hot encoding'], 'The median and the IQR barely move when outliers appear.'),
      info('Smoothing a target encoding', 'A category seen only 4 times has an unreliable mean. **Smooth** it towards the global mean:\n\n```\nencoded = (n × category_mean + m × global_mean) / (n + m)\n```\n\n`n` is the number of rows in the category and `m` is the smoothing strength. Rare categories move towards the global mean; common ones keep their own mean.'),
      type('A category has n = 4 rows, all positive (mean 1.0). The global mean is 0.2 and m = 16. What is the smoothed encoding?', ['0.36', '.36'], '(4 × 1.0 + 16 × 0.2) / 20 = 7.2 / 20.'),
      mc('`pd.qcut(df["income"], 4)` differs from `pd.cut(df["income"], 4)` because it…', ['Makes bins with about the same number of rows', 'Makes bins of the same width', 'Drops outliers', 'Sorts the table'], 'cut uses equal widths; qcut uses quantiles.'),
      mc('A column has 1,000,000 distinct categories. Which approach caps the number of columns?', ['The hashing trick, accepting some collisions', 'One-hot encoding', 'Ordinal codes by alphabet', 'Dropping the column is the only choice'], 'Hash each category into one of a fixed number of buckets.')),

    L('Common mistakes and debugging',
      info('The quiet pandas bugs', 'pandas rarely fails loudly. Chained assignment, silent joins and string dates all run and give plausible but wrong tables.\n\nBe in the habit of checking **row counts** and **a few rows by eye** after every merge, filter or group.'),
      mc('This code sometimes does not change df. Why?', ['It assigns to a temporary copy created by the first selection', 'There is no column named flag', 'The condition must use and', 'df is immutable'], 'Use df.loc[mask, "flag"] = 1.', 'df[df["age"] > 30]["flag"] = 1'),
      mc('This feature is meant to be each user’s past average spend. What is the problem?', ['It averages over all rows, including orders that happen after the prediction moment', 'transform returns a Series', 'mean cannot be used on amounts', 'It needs reset_index'], 'Use only earlier rows, for example an expanding mean shifted by one.', 'df["avg_spend"] = df.groupby("user_id")["amount"].transform("mean")'),
      mc('Dates are stored as strings like "2024-10-02". Why does this filter lose October?', ['String comparison puts "2024-10" before "2024-9"', 'The year is wrong', 'The > operator is not allowed', 'Strings cannot be filtered'], 'Convert with pd.to_datetime first.', 'recent = df[df["date"] > "2024-9-15"]'),
      mc('This line raises an error on a column that has missing values. Why?', ['Plain int cannot hold NaN, so the cast fails', 'astype needs two arguments', 'int is not a type', 'df["age"] is read-only'], 'Fill first, or use the nullable "Int64" type.', 'df["age"] = df["age"].astype(int)'),
      fillc('df["prev_amount"] = df.groupby("user_id")["amount"].___(1)', ['shift', 'diff', 'cumsum', 'rank'], 'shift(1) moves each value down one row within its group.'),
      mc('After `orders.merge(users, on="user_id")` you have fewer rows than orders. What is the cause?', ['An inner join drops orders whose user is missing from users', 'merge always deletes duplicates', 'The columns were sorted', 'It is a dtype bug'], 'Use how="left", and compare row counts.'),
      info('Guard rails', '- `validate="m:1"` in `merge` raises an error if the right-hand keys are not unique.\n- `assert len(out) == len(orders)` after a left join.\n- `df.sort_values(["user_id", "ts"])` before any rolling or shift.\n- Print `df.head()` after each step while developing.'),
      tf('`df.loc[mask, "col"] = value` is the safe way to assign to selected rows.', true, 'It writes to df itself rather than to a copy.'),
      order('Debugging a feature table with fewer rows than expected', ['Print the row count before and after each step', 'Find the step where the count changes', 'Inspect the keys that did not match', 'Switch to a left join with validate and fill the gaps deliberately', 'Add an assertion on the final row count'], 'Locate the step, then guard it.')),

    L('Case study: will this user buy this week?',
      info('The situation', 'A shop wants to predict, **as of a cutoff date**, whether each user will place an order in the **next 7 days**. Today you look at user 7 at the cutoff of **1 October**. Their orders:\n\n- 5 Sep: 40\n- 18 Sep: 25\n- 20 Sep: 35\n- 3 Oct: 50'),
      mc('Step 1: what is one row of the training table?', ['A user at one cutoff date, with features from before the cutoff and a label from the next 7 days', 'An order', 'A product', 'A user over their whole lifetime'], 'The row is defined by the prediction moment.'),
      type('Step 2: how many orders did the user place in the 30 days before 1 October?', ['3'], '5 Sep, 18 Sep and 20 Sep. The 3 Oct order is after the cutoff.'),
      type('Step 3: how many days have passed since the last order before the cutoff?', ['11'], '20 September to 1 October.'),
      type('Step 4: what is the label for this row (1 = bought in the next 7 days)?', ['1'], 'The 3 October order falls inside 1 to 8 October.'),
      info('One cutoff is not enough', 'Build **many cutoffs** (for example every Monday for a year) and stack the rows. This gives far more examples and covers seasonality. Keep **all rows of one user** in the same fold, and keep **time order** between training and test.'),
      mc('Step 5: which filter builds the features without leakage?', ['orders[orders["ts"] < cutoff]', 'orders[orders["ts"] <= cutoff + 7 days]', 'orders, unfiltered', 'orders[orders["ts"] > cutoff]'], 'Only the past is allowed.'),
      mc('Step 6: a new user has no orders before the cutoff. What do you do with "days since last order"?', ['Fill with a large value or leave it missing, and add a "no history" flag', 'Drop all new users', 'Fill with zero days', 'Use their first future order date'], 'Zero would say "just ordered", the opposite of the truth.'),
      mc('Step 7: how do you validate?', ['Train on earlier cutoffs, test on later ones, grouping users if they repeat', 'Random rows', 'Test on the earliest cutoffs', 'Use the training score'], 'Mirror how the model will be used.'),
      order('Order the pipeline', ['Choose cutoff dates and the label window', 'Filter orders to those before each cutoff', 'Aggregate per user: counts, recency, average value', 'Join the label from the following 7 days', 'Split by time and train a baseline'], 'Past for features, future for the label.')),

    L('Interview drill: feature engineering',
      info('What interviewers look for', 'Feature questions are really about **judgement**: do you ask what is known at prediction time, do you check that a feature helps, and do you worry about serving it live?'),
      match('Match the problem to a standard fix', [['Skewed money amounts', 'Log transform'], ['Hour of day', 'Sine and cosine'], ['Many rare categories', 'Group them into "other"'], ['Missing not at random', 'Add a missing-indicator column']]),
      mc('"How do you know a new feature helped?" Best answer?', ['Compare cross-validated scores with and without it, and check the gain exceeds fold-to-fold noise', 'It has high importance', 'Training loss fell', 'The code is shorter'], 'Measure on held-out data against the natural variation.'),
      mc('Cross-validated AUC goes from 0.810 to 0.812, and the standard deviation across folds is 0.01. What do you conclude?', ['The difference is within noise, so keep the simpler model unless more evidence appears', 'The new feature is a breakthrough', 'The folds are broken', 'AUC is the wrong metric'], 'A change much smaller than the spread is not evidence.'),
      mc('"How do you avoid training-serving skew for features?"', ['Share one feature definition between training and serving, for example through a feature store', 'Write the code twice and compare by eye', 'Retrain every minute', 'Skip validation'], 'Two implementations drift apart.'),
      info('Habits that impress', '- Say **when the feature is known**, before anything else.\n- Mention **leakage** and how you checked.\n- Start with a **simple baseline** and add feature groups one at a time.\n- Think about **missing values at serving time**, not only in training.'),
      fill('Scaling statistics must be learned on the ___ data only.', ['training', 'test', 'combined', 'future'], 'Otherwise information from the test set leaks in.'),
      mc('"You have 100 features and only 500 rows." What do you do?', ['Use a simple, regularised model, select features carefully and validate with repeated cross-validation', 'Fit the deepest model possible', 'Add 100 more features', 'Skip validation to save rows'], 'With few rows, extra freedom is mostly noise.'),
      tf('Tree models need one-hot encoding of every categorical feature to work at all.', false, 'Many libraries handle ordinal or native categorical input, though linear models need one-hot.'),
      order('Order a strong answer to "Walk me through your feature work on a customer table"', ['Ask when the prediction is made and what is known then', 'Build a baseline on raw columns', 'Add aggregates, recency and ratios computed only from the past', 'Validate each group with time-based cross-validation', 'Plan how the features will be served and monitored live'], 'Prediction moment first, serving last.'))
  ]
};
